+package githubro
+
+import (
+	"context"
+	"encoding/json"
+	"fmt"
+)
+
+// PullTitle reads a pull request title (GET only).
+func (c *Client) PullTitle(ctx context.Context, repo string, number int) (string, error) {
+	base, err := repoPath(repo)
+	if err != nil {
+		return "", err
+	}
+	b, err := c.get(ctx, fmt.Sprintf("%s/pulls/%d", base, number), "application/vnd.github+json")
+	if err != nil {
+		return "", err
+	}
+	var pr struct{ Title string `json:"title"` }
+	if err := json.Unmarshal(b, &pr); err != nil {
+		return "", fmt.Errorf("githubro: decode pull %s#%d: %w", repo, number, err)
+	}
+	return pr.Title, nil
+}
